mapper.select:
/* erp-mapper.xml id="selectErpContractList" 계약데이터 가져오기 */ SELECT tb1.mb_id , #{com_ym} AS com_ym , tb1.insco_cd , tb1.inspol_no , tb1.cont_date , tb1.mo_cd , tb1.policyholder , tb1.insured , tb1.ins_cont_type , tb1.prod_kind1 , tb1.prod_kind2 , tb1.prod_nm , IFNULL(tb1.main_contract_amt, 0) AS main_contract_amt , IFNULL(tb1.prem_amt, 0) AS prem_amt , IFNULL(tb1.dsnt_amt, 0) AS dsnt_amt , IFNULL(tb1.month_prem_amt, 0) AS month_prem_amt , tb1.napmethod , tb1.napgi , tb1.napgi_gbn , tb1.insu_strt_date , tb1.insu_end_date , IFNULL(tb1.term_insured, 0) AS term_insured , tb1.term_insured_gbn , IFNULL(tb1.insco_hwan, 0) AS insco_hwan , IFNULL(tb1.insco_hwan_2, 0) AS insco_hwan_2 , IFNULL(tb1.insco_hwan_3, 0) AS insco_hwan_3 , IFNULL(tb1.usi_insco_hwan, 0) AS usi_insco_hwan
, IFNULL(IFNULL(tb4.byenhwan_rate, tb1.hwan_rate), 0) AS hwan_rate , IFNULL(tb1.hwan, 0) AS hwan , IFNULL(tb1.usi_hwan, 0) AS usi_hwan , IFNULL(tb1.hyo_hwan, 0) AS hyo_hwan , IFNULL(tb1.hyo_byenhwan_rate, 0) AS hyo_byenhwan_rate , tb1.byenhwan_rate_gbn , IFNULL(tb1.napcnt, 0) AS napcnt , tb1.cont_status , tb1.cont_status_date , tb1.nap_datetime , tb1.nap_month , tb1.gijun_datetime , tb1.famliy_contract_type AS family_contract_type , tb1.db_contract_type , tb1.note_contract , tb1.transfer_type , tb1.normal_contract_type , tb1.switch_contract_type , tb1.mobile_contract_type FROM tbcn_contract tb1 JOIN tbin_empmst tb2 ON tb1.mb_id = tb2.mb_id AND tb1.mo_cd = tb2.emp_cd JOIN tbin_scd tb3 ON tb2.mb_id = tb3.mb_id AND tb2.scd = tb3.scd LEFT JOIN tbcn_byenhwan_rate tb4 ON tb1.mb_id = tb4.mb_id AND tb1.insco_cd = tb4.insco_cd AND tb1.prod_kind1 = tb4.prod_kind1 AND tb1.prod_kind2 = tb4.prod_kind2 AND CAST(tb1.napgi AS SIGNED) >= CAST(tb4.strt_napgi AS SIGNED) AND CAST(tb1.napgi AS SIGNED) < CAST(tb4.end_napgi AS SIGNED) AND tb4.com_ym = #{com_ym} WHERE tb1.mb_id = #{mb_id} AND tb1.cont_date >= DATE_FORMAT(CONCAT(#{com_ym}, '01'), '%Y-%m-%d')
AND tb1.cont_date <= DATE_FORMAT(LAST_DAY(DATE_FORMAT(CONCAT(#{com_ym}, '01'), '%Y-%m-%d')), '%Y-%m-%d')

/* erp-mapper.xml id="selectErpEmpSugumList" 인별 수금율 데이터 가져오기 */ SELECT tbX.mb_id , tbX.com_ym , tbX.emp_cd , tbX.insco_type , tbX.turn_cnt_gbn , CASE WHEN tbX.total_sugum_resource4 = 0 THEN NULL ELSE (tbX.total_sugum_result4 / tbX.total_sugum_resource4) * 100 END AS total_sugum_rate4 , CASE WHEN tbX.total_sugum_resource7 = 0 THEN NULL ELSE (tbX.total_sugum_result7 / tbX.total_sugum_resource7) * 100 END AS total_sugum_rate7 , CASE WHEN tbX.total_sugum_resource12 = 0 THEN NULL ELSE (tbX.total_sugum_result12 / tbX.total_sugum_resource12) * 100 END AS total_sugum_rate12 , CASE WHEN tbX.total_sugum_resource13 = 0 THEN NULL ELSE (tbX.total_sugum_result13 / tbX.total_sugum_resource13) * 100 END AS total_sugum_rate13 , CASE WHEN tbX.total_sugum_resource18 = 0 THEN NULL ELSE (tbX.total_sugum_result18 / tbX.total_sugum_resource18) * 100 END AS total_sugum_rate18 , CASE WHEN tbX.total_sugum_resource19 = 0 THEN NULL ELSE (tbX.total_sugum_result19 / tbX.total_sugum_resource19) * 100 END AS total_sugum_rate19 , CASE WHEN tbX.total_sugum_resource24 = 0 THEN NULL ELSE (tbX.total_sugum_result24 / tbX.total_sugum_resource24) * 100 END AS total_sugum_rate24 , CASE WHEN tbX.total_sugum_resource25 = 0 THEN NULL ELSE (tbX.total_sugum_result25 / tbX.total_sugum_resource25) * 100 END AS total_sugum_rate25 , CASE WHEN tbX.total_sugum_resource36 = 0 THEN NULL ELSE (tbX.total_sugum_result36 / tbX.total_sugum_resource36) * 100 END AS total_sugum_rate36 , CASE WHEN tbX.total_sugum_resource37 = 0 THEN NULL ELSE (tbX.total_sugum_result37 / tbX.total_sugum_resource37) * 100 END AS total_sugum_rate37 FROM (SELECT mb_id , com_ym , emp_cd , SUBSTRING(insco_cd, 1, 1) AS insco_type , turn_cnt_gbn , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4) AS total_sugum_resource4 , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7) AS total_sugum_resource7 , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7+tb1.sugum_resource8+tb1.sugum_resource9+tb1.sugum_resource10+tb1.sugum_resource11+tb1.sugum_resource12) AS total_sugum_resource12 /* 2~12회차 모집고 합 */ , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7+tb1.sugum_resource8+tb1.sugum_resource9+tb1.sugum_resource10+tb1.sugum_resource11+tb1.sugum_resource12+tb1.sugum_resource13) AS total_sugum_resource13 /* 2~13회차 모집고 합 */ , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7+tb1.sugum_resource8+tb1.sugum_resource9+tb1.sugum_resource10+tb1.sugum_resource11+tb1.sugum_resource12+tb1.sugum_resource13 +tb1.sugum_resource14+tb1.sugum_resource15+tb1.sugum_resource16+tb1.sugum_resource17+tb1.sugum_resource18) AS total_sugum_resource18 /* 2~18회차 모집고 합 */ , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7+tb1.sugum_resource8+tb1.sugum_resource9+tb1.sugum_resource10+tb1.sugum_resource11+tb1.sugum_resource12+tb1.sugum_resource13 +tb1.sugum_resource14+tb1.sugum_resource15+tb1.sugum_resource16+tb1.sugum_resource17+tb1.sugum_resource18+tb1.sugum_resource19) AS total_sugum_resource19 /* 2~19회차 모집고 합 */ , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7+tb1.sugum_resource8+tb1.sugum_resource9+tb1.sugum_resource10+tb1.sugum_resource11+tb1.sugum_resource12+tb1.sugum_resource13 +tb1.sugum_resource14+tb1.sugum_resource15+tb1.sugum_resource16+tb1.sugum_resource17+tb1.sugum_resource18+tb1.sugum_resource19+tb1.sugum_resource20+tb1.sugum_resource21+tb1.sugum_resource22+tb1.sugum_resource23+tb1.sugum_resource24) AS total_sugum_resource24 /* 2~24회차 모집고 합 */ , SUM(tb1.sugum_resource2 +tb1.sugum_resource3+tb1.sugum_resource4+tb1.sugum_resource5+tb1.sugum_resource6+tb1.sugum_resource7+tb1.sugum