, SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4) AS total_sugum_result4 , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7) AS total_sugum_result7 , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12) AS total_sugum_result12 /* 2~12회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13) AS total_sugum_result13 /* 2~13회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13 +tb1.sugum_result14+tb1.sugum_result15+tb1.sugum_result16+tb1.sugum_result17+tb1.sugum_result18) AS total_sugum_result18 /* 2~18회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13 +tb1.sugum_result14+tb1.sugum_result15+tb1.sugum_result16+tb1.sugum_result17+tb1.sugum_result18+tb1.sugum_result19) AS total_sugum_result19 /* 2~19회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13 +tb1.sugum_result14+tb1.sugum_result15+tb1.sugum_result16+tb1.sugum_result17+tb1.sugum_result18+tb1.sugum_result19+tb1.sugum_result20+tb1.sugum_result21+tb1.sugum_result22+tb1.sugum_result23+tb1.sugum_result24) AS total_sugum_result24 /* 2~24회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13 +tb1.sugum_result14+tb1.sugum_result15+tb1.sugum_result16+tb1.sugum_result17+tb1.sugum_result18+tb1.sugum_result19+tb1.sugum_result20+tb1.sugum_result21+tb1.sugum_result22+tb1.sugum_result23+tb1.sugum_result24+tb1.sugum_result25) AS total_sugum_result25 /* 2~24회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13 +tb1.sugum_result14+tb1.sugum_result15+tb1.sugum_result16+tb1.sugum_result17+tb1.sugum_result18+tb1.sugum_result19+tb1.sugum_result20+tb1.sugum_result21+tb1.sugum_result22+tb1.sugum_result23+tb1.sugum_result24+tb1.sugum_result25 +tb1.sugum_result26+tb1.sugum_result27+tb1.sugum_result28+tb1.sugum_result29+tb1.sugum_result30+tb1.sugum_result31+tb1.sugum_result32+tb1.sugum_result33+tb1.sugum_result34+tb1.sugum_result35+tb1.sugum_result36) AS total_sugum_result36 /* 2~36회차 유지고 합 */ , SUM(tb1.sugum_result2+tb1.sugum_result3+tb1.sugum_result4+tb1.sugum_result5+tb1.sugum_result6+tb1.sugum_result7+tb1.sugum_result8+tb1.sugum_result9+tb1.sugum_result10+tb1.sugum_result11+tb1.sugum_result12+tb1.sugum_result13 +tb1.sugum_result14+tb1.sugum_result15+tb1.sugum_result16+tb1.sugum_result17+tb1.sugum_result18+tb1.sugum_result19+tb1.sugum_result20+tb1.sugum_result21+tb1.sugum_result22+tb1.sugum_result23+tb1.sugum_result24+tb1.sugum_result25 +tb1.sugum_result26+tb1.sugum_result27+tb1.sugum_result28+tb1.sugum_result29+tb1.sugum_result30+tb1.sugum_result31+tb1.sugum_result32+tb1.sugum_result33+tb1.sugum_result34+tb1.sugum_result35+tb1.sugum_result36+tb1.sugum_result37) AS total_sugum_result37 /* 2~37회차 유지고 합 */ FROM tbcn_contract_sugum_emp_month tb1 WHERE mb_id = #{mb_id} AND com_ym = #{com_ym} GROUP