/* erp-mapper.xml id="selectErpRoleList" ERP 권한 목록 조회 */ SELECT mb_id /* 회사코드 VARCHAR2(20) */ , role_id /* 권한ID VARCHAR2(50) */ , REPLACE(role_id, 'ROLE_', '') AS replace_role_id /* 권한ID VARCHAR2(50) */ , role_nm /* 권한명 VARCHAR2(50) */ , login_autr_type /* 로그인 인증 초기 설정 VARCHAR2(1) */ , in_emp_cd /* 입력자사번 VARCHAR2(20) */ , DATE_FORMAT(in_dtm, '%Y-%m-%d %T') AS in_dtm /* 입력일시 TIMESTAMP */ , up_emp_cd /* 수정자사번 VARCHAR2(20) */ , DATE_FORMAT(up_dtm, '%Y-%m-%d %T') AS up_dtm /* 수정일시 TIMESTAMP */ FROM tbsy_roles_map /* [SY][시스템] 롤마스터 */ WHERE mb_id = #{mb_id}
AND role_id != 'ROLE_0'
ORDER BY CAST(REPLACE(role_id, 'ROLE_', '') AS UNSIGNED)

/* role-mapper.xml id="selectErpRolesHierarchyView" ERP에서 해당 권한이 있는지 조회 */

SELECT chld_role_id as name
  FROM hierarchy_cte
 WHERE chld_role_id = #{check_role_id}

/* erp-mapper.xml id="selectErpUserRoleListCount" ERP 사용자 권한 메핑 겸직여부 조회  */
SELECT COUNT(emp_cd) AS concurrent_gubun
  FROM tbsy_user_role_map
 WHERE mb_id = #{mb_id}
   AND emp_cd = #{emp_cd}
 GROUP BY mb_id, emp_cd

/* erp-mapper.xml id="selectEmpSchList" ERP 인사목록 조회(권한사원 변경용) */ WITH recursive org_cte AS (SELECT 1 AS level , CONCAT(tb2.sort_no,tb2.snm) AS ordersb , CONCAT(' > ',CAST(tb2.scd AS CHAR (509))) AS scdpath , CONCAT(' > ',CAST(tb2.snm AS CHAR (509))) AS snmpath , tb2.mb_id , tb2.scd /* 조직코드 VARCHAR(20) */ , tb2.snm /* 조직명 VARCHAR(50) */ , tb2.pscd /* 상위조직코드 VARCHAR(20) */ , tb2.org_unit_gbn /* 조직단위구분 VARCHAR(10) */ , tb2.org_unit_detail_gbn /* 조직 단위 상세 구분 VARCHAR(10) */ , tb2.org_strt_ymd /* 조직생성년월일 VARCHAR(10) */ , tb2.org_end_ymd /* 조직폐쇄년월일 VARCHAR(10) */ , tb2.scd_head /* 조직장 VARCHAR(10) */ , tb2.org_mng_gbn /* 영업조직여부 VARCHAR(1) */ , tb2.use_yn /* 사용여부 VARCHAR(1) */ , tb2.sort_no /* 정렬순서 BIGINT */ , tb2.memo /* 비고 VARCHAR(200) */ FROM (SELECT * FROM tbin_scd tb1 WHERE mb_id = #{mb_id} AND pscd IS NULL ) tb2 UNION ALL SELECT level+1 AS level , CONCAT(org_cte.ordersb,LPAD(tb3.sort_no,4,'0'),tb3.snm) AS ordersb , CONCAT(scdpath,' > ',tb3.scd) AS scdpath , CONCAT(snmpath,' > ',tb3.snm) AS snmpath , tb3.mb_id , tb3.scd /* 조직코드 VARCHAR(20) */ , tb3.snm /* 조직명 VARCHAR(50) */ , tb3.pscd /* 상위조직코드 VARCHAR(20) */ , tb3.org_unit_gbn /* 조직단위구분 VARCHAR(10) */ , tb3.org_unit_detail_gbn /* 조직 단위 상세 구분 VARCHAR(10) */ , tb3.org_strt_ymd /* 조직생성년월일 VARCHAR(10) */ , tb3.org_end_ymd /* 조직폐쇄년월일 VARCHAR(10) */ , tb3.scd_head /* 조직장 VARCHAR(10) */ , tb3.org_mng_gbn /* 영업조직여부 VARCHAR(1) */ , tb3.use_yn /* 사용여부 VARCHAR(1) */ , tb3.sort_no /* 정렬순서 BIGINT */ , tb3.memo /* 비고 VARCHAR(200) */ FROM (SELECT * FROM tbin_scd WHERE mb_id = #{mb_id} ) tb3 JOIN org_cte ON tb3.mb_id = org_cte.mb_id AND tb3.pscd = org_cte.scd ) SELECT tb1.seq /* 일련번호 bigint(20)*/ , tb1.mb_id /* 회사코드 varchar(20)*/ , tb1.emp_cd /* 사원코드 varchar(20)*/ , tb1.emp_nm /* 사원명 varchar(20)*/ , tb1.emp_nme /* 영문명 varchar(50)*/ , tb1.scd /* 조직코드 varchar(20)*/ , tb2.snm , CASE WHEN tb2.pscd IS NULL THEN tb2.snm ELSE SUBSTRING(SUBSTRING(tb2.snmpath, 4), CHAR_LENGTH(fn_get_pathroot(SUBSTRING(tb2.snmpath,4), ' > ', 1)) + 4) END AS snmpath , tb1.jikgub /* 직급코드 varchar(20)*/ , tb3.cd_vl_nm AS jikgub_nm , tb1.jikchk /* 직책코드 varchar(20)*/ , tb4.cd_vl_nm AS jikchk_nm , tb1.empsta /* 재직여부 varchar(20)*/ , tb5.cd_vl_nm AS empsta_nm , tb1.ent_ymd /* 입사일자 varchar(10)*/ , tb1.gent_ymd /* 위촉일자 varchar(10)*/ , tb1.reentry_ymd /* 재입사일자 varchar(10)*/ , tb1.end_ymd /* 퇴사일자 varchar(10)*/ , tb1.out_ymd /* 해촉일자 varchar(10)*/ , tb6.role_id , tb7.role_nm FROM tbin_empmst tb1 LEFT JOIN org_cte tb2 ON tb1.mb_id = tb2.mb_id AND tb1.scd = tb2.scd LEFT JOIN tbcm_common_code tb3 ON tb1.mb_id = tb3.mb_id AND tb1.jikgub = tb3.cd_vl AND tb3.grp_cmm_cd = 'JIKGUB' LEFT JOIN tbcm_common_code tb4 ON tb1.mb_id = tb4.mb_id AND tb1.jikchk = tb4.cd_vl AND tb4.grp_cmm_cd = 'JIKCHK' LEFT JOIN tbcm_common_code tb5 ON tb1.mb_id = tb5.mb_id AND tb1.empsta = tb5.cd_vl AND tb5.grp_cmm_cd = 'EMPSTA' LEFT JOIN tbsy_user_role_map tb6 ON tb1.mb_id = tb6.mb_id AND tb1.emp_cd = tb6.emp_cd AND tb6.concurrent_idx = 1 LEFT JOIN tbsy_roles_map tb7 ON tb6.mb_id = tb7.mb_id AND tb6.role_id = tb7.role_id WHERE tb1.mb_id = #{mb_id} AND tb1.emp_cd NOT IN ()
AND ( tb1.emp_nm LIKE CONCAT('%',#{search_word},'%') OR tb1.emp_cd LIKE CONCAT('%',UPPER(#{search_word}),'%') )
ORDER BY tb1.emp_cd

/* erp-mapper.xml selectProductgroupKind2 상품구분2 조회 (dropDownList) */
SELECT prod_kind2 AS prod_kind2
     , prod_kind2 AS prod_kind2_nm
     , CONCAT(insco_type, seq) AS prod_kind2_gubun
     , insco_type
  FROM tbcn_product_group
 WHERE mb_id = #{mb_id}
   AND use_yn = 'Y'

    AND insco_type = #{srch_insco_type}


    AND prod_kind1 = #{srch_prod_kind1}
